func (c *MarketHTTPClientImpl) SetWatchlist(ctx context.Context, in *SetWatchlistRequest, opts ...http.CallOption) (*SetWatchlistReply, error) {
	var out SetWatchlistReply
	pattern := "/v1/market/watchlist"
	path := binding.EncodeURL(pattern, in, false)
	opts = append(opts, http.Operation(OperationMarketSetWatchlist))
	opts = append(opts, http.PathTemplate(pattern))
	err := c.cc.Invoke(ctx, "POST", path, in, &out, opts...)
	if err != nil {
		return nil, err
	}
	return &out, nil
}
